'use strict';
function enrollRouterDialog(deviceId=''){
 const device=deviceId?find('devices',deviceId):null;
 $('#detail-dialog').close();$('#editor-title').textContent=device?'Connection script — '+device.name:'Connect MikroTik with a script';
 $('#editor-description').textContent='RouterOS 7.16 or later. The router sends monitoring reports to Network Hub over HTTPS every 30 seconds.';
 $('#editor-fields').innerHTML=(device?'<p>'+h(device.connectionConfigured?'Generating a replacement invalidates the previous connection credential. Install the new script on this router afterward.':'Generate the script, then paste the entire block into this router’s terminal.')+'</p>':'<label>Router name<input name="routerName" required maxlength="250" placeholder="Main site MikroTik"></label>')+'<div class="field-note">Reports identity, CPU, memory, uptime, up to 64 interfaces and 32 IPv4 default routes. Creates only the Network Hub script and scheduler. Your existing LAN, firewall, VPN, RADIUS and customer access configuration stays in place.</div><label class="check-label"><input name="reviewed" type="checkbox" required> I will keep the generated script private and install it on the intended router.</label>'+(device?.driver==='routeros-script'&&device.connectionConfigured?'<button class="button ghost danger" type="button" data-revoke-router-agent="'+device.id+'">Revoke this connection</button>':'');
 $('#editor-error').textContent='';$('#editor-form [type=submit]').textContent='Generate connection script';$('#editor').showModal();
 $('#editor-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('[type=submit]',form);if(device?.connectionConfigured&&!confirm('Replace this router’s current monitoring connection? The previous credential stops working immediately.'))return;button.disabled=true;try{const result=await api('router-agent/enroll','POST',device?{deviceId:device.id}:{name:form.elements.routerName.value});form.reset();$('#editor').close();await load();render();showRouterScript(result);}catch(error){$('#editor-error').textContent=error.message;}finally{button.disabled=false;}};
}
function showRouterScript(result){
 showDetails('Install script — '+result.device.name,`<p>Copy or download this script, then paste the entire block into your MikroTik terminal as an administrator. Keep it private: it contains a token that can report for this router.</p><div class="setup-actions"><button class="button primary" data-copy-router-script>Copy script</button><button class="button secondary" data-download-router-script>Download .rsc</button></div><label>RouterOS connection script<textarea id="router-script-source" class="router-script-source" readonly rows="18" spellcheck="false">${h(result.script)}</textarea></label><h3>After installation</h3><ol><li>Check for “Network Hub agent installed” in the terminal.</li><li>Open Routers and wait for an authenticated check-in, normally within 30 seconds.</li><li>If it stays pending, check the router’s clock, Internet access, trusted certificates and the Network Hub warnings in its log.</li></ol><p>This connection reports monitoring data. VPN access, RADIUS authentication and remote configuration are separate services. The script does not download or import remote commands.</p>`);
 $('#detail-dialog').dataset.routerScript=result.device.id;
}
document.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;try{
 if(button.hasAttribute('data-new-router-agent'))enrollRouterDialog();
 if(button.dataset.routerAgent)enrollRouterDialog(button.dataset.routerAgent);
 if(button.hasAttribute('data-copy-router-script')){const source=$('#router-script-source');await navigator.clipboard.writeText(source.value);toast('Connection script copied. Keep it private.');}
 if(button.hasAttribute('data-download-router-script')){const source=$('#router-script-source'),blob=new Blob([source.value],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='network-hub-'+$('#detail-dialog').dataset.routerScript+'.rsc';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 if(button.dataset.revokeRouterAgent){if(!confirm('Revoke this router’s script credential? Its check-ins will stop until you install a new script.'))return;await api('router-agent/'+button.dataset.revokeRouterAgent+'/credential','DELETE',{});$('#editor').close();await load();render();toast('Router connection revoked');}
 }catch(error){toast(error.message);}});
$('#editor').addEventListener('close',()=>{$('#editor-form [type=submit]').textContent='Save';});
$('#detail-dialog').addEventListener('close',()=>{if($('#detail-dialog').dataset.routerScript){$('#detail-content').replaceChildren();delete $('#detail-dialog').dataset.routerScript;}});
